def bsearch(xs, x):
    left, right = 0, len(xs) - 1
    while left <= right:
        mid = (left + right) // 2
        if xs[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    if xs[left] == x:
        return left
    return -1
```

